import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { DocumentReadOutcome } from '../document-facts-reader.ts';
import { createPayslipAnalysisStore } from './payslip-analysis.ts';

/**
 * Test-only (FIN-02): the RECORDED backend of the Payslip Analysis screen. `fixtures/payslip-analysis-fixtures.json` is
 * GENERATED by the backend's controllers/payslip-analysis.contract.test.ts from the REAL `/api/profile/resolve` and
 * `/api/pro/payslip-replay` (by reference) on synthetic payslips, and re-checked there on every run. No AI, no network.
 */

const here = path.dirname(fileURLToPath(import.meta.url));

export interface RecordedCase { read: DocumentReadOutcome & { status: 'done' }; resolve: Record<string, unknown>; replay: Record<string, unknown> }
export const FIXTURES = JSON.parse(readFileSync(path.join(here, 'fixtures', 'payslip-analysis-fixtures.json'), 'utf-8')) as { today: string; cases: Record<string, RecordedCase> };
export type CaseName = keyof typeof FIXTURES.cases & string;

export interface Call { url: string; body: Record<string, unknown> | null }

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

export function payslipHarness(name: string, options: {
  vision?: boolean | null;
  read?: DocumentReadOutcome | (() => Promise<DocumentReadOutcome>);
  resolve?: { status: number; body: unknown };
  replay?: { status: number; body: unknown };
} = {}) {
  const recorded = FIXTURES.cases[name] as RecordedCase;
  const calls: Call[] = [];
  const reads: Array<{ name: string; kind: string }> = [];
  const fetchImpl = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(input);
    const body = typeof init?.body === 'string' ? (JSON.parse(init.body) as Record<string, unknown>) : null;
    calls.push({ url, body });
    if (url === '/api/profile/resolve') return options.resolve ? json(options.resolve.status, options.resolve.body) : json(200, recorded.resolve);
    if (url === '/api/pro/payslip-replay') return options.replay ? json(options.replay.status, options.replay.body) : json(200, recorded.replay);
    throw new Error(`unexpected request ${url}`);
  }) as typeof fetch;
  const store = createPayslipAnalysisStore({
    fetchImpl,
    readFacts: async (file, kind) => {
      reads.push({ name: file.name, kind });
      if (typeof options.read === 'function') return options.read();
      return options.read ?? { ...recorded.read, factBatches: [{ synthetic: true }] };
    },
    readerStatus: async () => (options.vision === undefined ? true : options.vision),
    today: () => FIXTURES.today,
  });
  return { store, calls, reads, recorded };
}

export const pdf = (name = 'synthetic-payslip.pdf') => new File([new Uint8Array([37, 80, 68, 70])], name, { type: 'application/pdf' });

/** A store driven through select -> read with the recorded case. */
export async function analysed(name: string, options: Parameters<typeof payslipHarness>[1] = {}) {
  const h = payslipHarness(name, options);
  await h.store.checkReader();
  h.store.selectFile(pdf());
  await h.store.read();
  return h;
}
